/bin/bash -lc "python - <<'PY'
import urllib.request, json
for repo in ['scanpy','anndata','h5py']:
    url=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?limit=20'
    try:
        with urllib.request.urlopen(url, timeout=30) as r:
            data=json.load(r)
        print('REPO', repo)
        for t in data.get('tags', [])[:10]:
            print(t.get('name'))
    except Exception as e:
        print('ERR', repo, type(e).__name__, e)
PY"
